function home(){return `<main id="main" class="wrap"><section class="hero"><div><div class="issue-label"><b>ISSUE 01</b><span>2026.10.17 · 第一堂课</span></div><div class="eyebrow">FROM THE VINEYARD TO THE GLASS</div><h1>好酒的故事，<span class="hero-line">从<em>一株葡萄藤</em>开始。</span></h1><p class="intro">把课堂上的每一个「为什么」，<br>慢慢连成杯中风味的答案。<br>这是一份陪你走向 WSET Ⅲ 的学习期刊。</p><div class="hero-actions"><a href="#lesson/${lessons.find(l=>!completed.includes(l.id))?.id||'roots'}" class="primary">${count()?'继续本期学习':'开始本期学习'} <span>↗</span></a><a class="text-link" href="#quiz">课后小测 →</a></div><div class="hero-foot"><span>6 个阅读单元</span><span>·</span><span>可分六次阅读</span><span>·</span><span>讲义 × 课堂笔记</span></div></div><figure class="hero-art" style="margin:0"><img src="assets/vineyard.webp" alt="手绘秋日葡萄园，葡萄藤沿山坡延伸，远处有酒庄与群山" fetchpriority="high"><div class="floating-label"><span>01</span><div>葡萄藤与生长环境<small>THE VINE & ITS ENVIRONMENT</small></div></div><figcaption class="art-caption"><span>FIELD NOTES / SESSION 1</span><span>从土地，读懂风味。</span></figcaption></figure></section><div class="session-strip"><div class="strip-title"><span class="dot"></span><strong>正在学习 · Session 1</strong><small>葡萄藤、砧木、气候与土壤</small></div><div class="progress-wrap"><span>本期阅读进度</span>${progress()}<span>${count()} / 6</span></div></div><div class="guide-banner"><div><span class="eyebrow">SOURCE RECONCILIATION</span><p>讲义与课堂细节已补回各章，另附课程说明、作业与待核对记录。</p></div><a href="#guide">本期导读与收录核对 ↗</a></div><section class="s2-promo"><div><span class="eyebrow">NEW ISSUE / SESSION 2 · 2026.10.18</span><h2 class="two-line-title"><span>从葡萄藤的生长，</span><span>走向葡萄园的管理。</span></h2><p>第二课已收录：整枝与修剪、冠层、产量、病虫害和采收。讲义与课堂转写逐页对照。</p></div><a class="primary" href="#session2">进入 Session 2 ↗</a></section><section id="chapters"><div class="section-head"><div><div class="eyebrow">IN THIS ISSUE</div><h2>沿着葡萄藤，建立第一张知识地图。</h2></div><p>从结构到环境<br>六个单元，逐步理解</p></div><div class="chapter-grid">${lessons.map(l=>`<a class="chapter" href="#lesson/${l.id}"><div class="chapter-art" style="--tint:${l.tint}"><span class="chapter-no">${l.n}</span>${diagrams[l.id]()}</div><div class="chapter-body"><div class="chapter-meta">${l.en}</div><h3>${l.short}</h3><p>${l.desc}</p><div class="chapter-bottom"><span>讲义 p.${l.pages} · ${l.duration} 分钟</span><span>${completed.includes(l.id)?'✓ 已完成':'阅读全文'} <b>↗</b></span></div></div></a>`).join('')}</div></section><aside class="editor-note"><div><div class="eyebrow">A NOTE FROM 小 P</div><h3 class="two-line-title"><span>别只记结论，</span><span>把原因讲出来。</span></h3></div><p>这堂课先练习一个习惯：<strong>自然条件 → 葡萄藤与果实的变化 → 葡萄酒的风格、品质或成本。</strong><br>看到「朝南的坡面」，再追问为什么阳光更多；看到「砧木」，再说清它解决什么问题。每多解释一步，零散的知识就更容易连起来。</p></aside><section class="bottom-grid"><div><div class="eyebrow">THE NEXT CHAPTERS</div><h2>一本会继续生长的学习期刊。</h2><a class="future-row" href="#session2"><span class="num">02</span><span>葡萄园管理</span><span>已收录 ↗</span></a><div class="future-row"><span class="num">03</span><span>发酵、陈年与白／甜葡萄酒</span><span>待加入</span></div><div class="future-row"><span class="num">04</span><span>红葡萄酒与桃红葡萄酒</span><span>待加入</span></div><div class="future-row"><span class="num">05–06</span><span>法规、价格与法国产区</span><span>待加入</span></div></div><div class="review-teaser"><div class="eyebrow" style="color:#9a6b70">PAUSE & RECALL</div><h2 class="two-line-title"><span>合上讲义，</span><span>你能解释几个「为什么」？</span></h2><p>8 道即时反馈小测 + 1 道解释练习。<br>先试着回答，再回到对应章节补上遗漏。</p><a href="#quiz">开始 Session 1 自测 <span>↗</span></a></div></section></main>`}
function lessonView(id){const l=lessons.find(x=>x.id===id);if(!l)return `<main class="wrap" id="main"><h1>暂未找到这个章节</h1><a href="#home">返回学习期刊 →</a></main>`;const i=lessons.indexOf(l),next=lessons[i+1];return `<main id="main" class="lesson-shell"><aside class="lesson-rail"><a href="#home" class="back">← 返回学习期刊</a><div class="eyebrow">SESSION 1 · CONTENTS</div><p class="rail-title">葡萄藤与生长环境</p><nav class="rail-list" aria-label="本期章节">${lessons.map(x=>`<a href="#lesson/${x.id}" class="${l.id===x.id?'active':''}" ${l.id===x.id?'aria-current="page"':''}><span>${x.n}</span>${x.short}<i>${completed.includes(x.id)?'✓':''}</i></a>`).join('')}</nav><a class="rail-guide" href="#workbook/1">Session 1 练习册 ↗</a><a class="rail-guide" href="#guide">课程导读 · 作业 · 资料核对 ↗</a><div class="rail-progress">本期已完成 ${count()} / 6${progress()}</div></aside><article class="lesson-content"><div class="eyebrow">CHAPTER ${l.n} / ${l.en}</div><h1>${l.title}</h1><p class="lesson-deck">${l.deck}</p><div class="source-meta"><span>讲义 p.${l.pages}</span><span>课堂转写 ${l.time}</span><span>约 ${l.duration} 分钟阅读</span></div><figure style="margin:0"><div class="lesson-visual" style="--tint:${l.tint}">${diagrams[l.id]()}</div><figcaption class="fig-caption">${l.caption}</figcaption></figure>${l.body}<details class="recall"><summary>停下来想一想 · ${l.question}</summary><p>${l.answer}</p></details><div class="notes"><label for="note-${l.id}">我的随手笔记 <small id="note-status">仅保存在当前浏览器</small></label><textarea id="note-${l.id}" data-note="${l.id}" placeholder="用自己的话解释这个知识点，或记下想问老师的问题……">${safe(read(notesKey(l.id),''))}</textarea></div><div class="lesson-end"><button class="complete-btn ${completed.includes(l.id)?'done':''}" data-complete="${l.id}">${completed.includes(l.id)?'✓ 已完成阅读':'○ 标记本章已读'}</button><a class="next-link" href="${next?'#lesson/'+next.id:'#quiz'}">${next?'下一章 · '+next.short:'完成阅读，试试自测'} →</a></div></article></main>`}
function mapView(){return `<main id="main" class="wrap"><div class="page-intro"><div class="eyebrow">CONNECT THE DOTS</div><h1 class="page-title">把知识，酿成理解。</h1><p>这是 Session 1 的连接图。学习新产区时，仍可以沿着同一条因果链提问。</p></div><div class="map-layout"><section class="map-panel full"><div class="eyebrow">THE CENTRAL THREAD</div><h2>先从条件出发，再解释杯中的结果。</h2><div class="concept-flow"><a href="#lesson/climate">自然条件<small>气候 · 天气 · 土壤 · 地形</small></a><span>→</span><a href="#lesson/cycle">葡萄与生长<small>健康 · 产量 · 成熟 · 果实成分</small></a><span>→</span><a href="#lesson/climate">葡萄酒表现<small>风格 · 品质潜力 · 生产成本</small></a></div></section><section class="map-panel"><div class="eyebrow">THE VINE</div><h2>葡萄藤本身</h2>${lessons.slice(0,3).map(l=>`<a class="map-node" href="#lesson/${l.id}"><span>↗</span>${l.short}<small>${l.desc}</small></a>`).join('')}</section><section class="map-panel"><div class="eyebrow">THE ENVIRONMENT</div><h2>它生长的环境</h2>${lessons.slice(3).map(l=>`<a class="map-node" href="#lesson/${l.id}"><span>↗</span>${l.short}<small>${l.desc}</small></a>`).join('')}</section><section class="map-panel full"><div class="eyebrow">WORDS WORTH KNOWING</div><h2>先认清术语，再串联知识。</h2><div class="tag-row">${[['根瘤蚜 Phylloxera','roots'],['接穗 Scion','roots'],['砧木 Rootstock','roots'],['种内杂交 Crossing','propagation'],['种间杂交 Hybrid','propagation'],['转色 Véraison','cycle'],['大陆度 Continentality','climate'],['昼夜温差 Diurnal range','climate'],['朝向 Aspect','soil']].map(([t,id])=>`<a href="#lesson/${id}" class="tag">${t} ↗</a>`).join('')}</div></section><section class="map-panel full"><div class="eyebrow">NEXT TO CONNECT</div><h2>把环境与「人的选择」连起来。</h2><p class="lesson-deck">Session 2 已加入讲义、课堂转写与课本第6章：<a href="#session2">从密度、整枝和冠层，到病虫害与采收，继续阅读 →</a></p></section></div></main>`}
function feedback(i){const a=answers[i],q=questions[i];if(a===undefined)return '';const ok=a===q.correct;return `<div class="quiz-feedback ${ok?'':'wrong-feedback'}" role="status"><strong>${ok?'✓ 理解正确':'再看一步 · 正确答案是 '+String.fromCharCode(65+q.correct)}</strong><br>${q.why}<a href="#lesson/${q.lesson}">回到「${lessons.find(l=>l.id===q.lesson).short}」 →</a></div>`}
function quizView(){const n=Object.keys(answers).filter(k=>questions[k]).length,score=questions.filter((q,i)=>answers[i]===q.correct).length;return `<main id="main" class="wrap"><div class="page-intro"><div class="eyebrow">PAUSE & RECALL · SESSION 1</div><h1 class="page-title">把「记得」变成「会解释」。</h1><p>先独立作答，再查看解释。这里的题目用于查漏补缺，不是官方真题。</p></div><p class="wb-entry"><a class="primary" href="#workbook/1">Session 1 练习册 · 简答与品种表 ↗</a> <a class="text-link" href="#workbook/2">Session 2 练习册 ↗</a></p><div class="quiz-layout"><div>${questions.map((q,i)=>`<section class="quiz-card" id="question-${i}"><div class="eyebrow">QUESTION ${String(i+1).padStart(2,'0')} / 08</div><h2>${q.q}</h2>${q.options.map((o,j)=>`<button class="option ${answers[i]!==undefined?(j===q.correct?'correct':answers[i]===j?'wrong':''):''}" data-question="${i}" data-answer="${j}" ${answers[i]!==undefined?'disabled':''}>${String.fromCharCode(65+j)} · ${o}</button>`).join('')}${feedback(i)}</section>`).join('')}<section class="quiz-card"><div class="eyebrow">WRITE TO UNDERSTAND</div><h2>解释：为什么潮湿地区与干旱地区，对土壤水分管理的需求可能不同？</h2><p class="fine">自编解释练习 · 不设官方分值。先写 3—5 句，再展开检查思路。</p><textarea class="short-answer" data-note="practice" aria-label="解释练习答案" placeholder="尝试按「条件 → 影响 → 选择」写出完整句子。">${safe(read(notesKey('practice'),''))}</textarea><details class="recall"><summary>写完后，检查自己的因果链</summary><div class="checklist"><label><input type="checkbox">潮湿地区需要避免根区长期积水，并重视排水。</label><label><input type="checkbox">干旱地区需要保存足够的土壤水分供根系吸收。</label><label><input type="checkbox">严重缺水会限制生长、光合作用及成熟。</label><label><input type="checkbox">判断还结合降雨、土壤与灌溉，而不是宣布某种土壤永远最好。</label></div></details></section></div><aside class="quiz-summary"><div class="eyebrow">YOUR RECALL</div><div class="score"><span id="quiz-score">${score}</span><small style="font-size:20px"> / 8</small></div><h3>第一轮，找出盲点。</h3><p id="quiz-progress">已回答 ${n} / 8 题${n===8?' · 本轮完成':''}</p><p>答错并不浪费。回到对应章节，用自己的话解释一次，再重新练习。</p><button id="reset-quiz">重新开始本轮 ↻</button></aside></div></main>`}
function render(){const hash=location.hash.slice(1)||'home',route=hash.split('/')[0];$('#app').innerHTML=route==='workbook'?workbookView(hash.split('/')[1]):route==='session2'?s2View(hash.split('/')[1]):route==='session2quiz'?s2Quiz():route==='session2sources'?s2Sources():route==='lesson'?lessonView(hash.split('/')[1]):route==='map'?mapView():route==='quiz'?quizView():route==='guide'?guideView():home();document.querySelectorAll('[data-nav]').forEach(a=>{const yes=a.dataset.nav===(route.startsWith('session2')?'session2':(route==='lesson'||route==='guide')?'home':route==='workbook'?'quiz':route);a.classList.toggle('active',yes);if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=route.startsWith('session2')?`${route==='session2'?(s2Units.find(u=>u.id===hash.split('/')[1])?.short||'葡萄园管理'):route==='session2quiz'?'Session 2 自测':'Session 2 资料核对'} · WSET Ⅲ 通关指南`:route==='lesson'?`${lessons.find(l=>l.id===hash.split('/')[1])?.short||'章节'} · WSET Ⅲ 通关指南`:`${route==='quiz'?'练习与复习 · ':route==='map'?'知识地图 · ':''}WSET Ⅲ 通关指南`;window.scrollTo(0,0);bindPage()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function bindPage(){bindSession2();document.querySelectorAll("[data-course-task]").forEach(el=>el.addEventListener("change",()=>save("wset3-task-"+el.dataset.courseTask,el.checked)));document.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{const ok=save(notesKey(el.dataset.note),el.value);const s=$('#note-status');if(s)s.textContent=ok?'已保存到当前浏览器':'当前浏览器无法保存，请复制备份'}));document.querySelectorAll('[data-complete]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.complete;completed=completed.includes(id)?completed.filter(x=>x!==id):[...completed,id];const ok=save('wset3-completed',completed);const y=window.scrollY;render();window.scrollTo(0,y);toast(ok?(completed.includes(id)?'本章已完成，进度已保存。':'已取消本章完成标记。'):'当前浏览器无法保存进度。')}));document.querySelectorAll('[data-question]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.question),a=Number(b.dataset.answer);answers[i]=a;save('wset3-answers',answers);const q=questions[i],card=$('#question-'+i);card.querySelectorAll('.option').forEach((o,j)=>{o.disabled=true;o.classList.toggle('correct',j===q.correct);o.classList.toggle('wrong',j===a&&a!==q.correct)});card.insertAdjacentHTML('beforeend',feedback(i));$('#quiz-score').textContent=questions.filter((q,j)=>answers[j]===q.correct).length;const n=Object.keys(answers).filter(k=>questions[k]).length;$('#quiz-progress').textContent=`已回答 ${n} / 8 题${n===8?' · 本轮完成':''}`}));$('#reset-quiz')?.addEventListener('click',()=>{answers={};save('wset3-answers',answers);render();toast('已开始新一轮练习。')})}
const searchTerms=[['根瘤蚜 Phylloxera','roots','根系受损与抗性砧木'],['接穗 Scion / 砧木 Rootstock','roots','地上品种与根系的分工'],['嫁接 Grafting / 室内 / 田间换接','roots','连接植株部分，不等于杂交'],['无性繁殖 / 扦插 / 品系 Clone','propagation','保留品种身份'],['种内杂交 Crossing / 种间杂交 Hybrid','propagation','分清种、品种和后代'],['冬眠 / 萌芽 / 开花 / 坐果 / 转色 Véraison','cycle','葡萄藤的年周期'],['光合作用 / 高温 / 干旱 / 糖','needs','需求与极端条件的限制'],['霜冻 Frost / 冬季冻害 Freeze / 防霜喷灌','needs','区分组织与风险'],['气候 / 天气 / 年份差异','climate','长期常态与当年实际状况'],['大陆性 / 海洋性 / 地中海 / 大陆度 / 昼夜温差','climate','分清两种分类维度'],['海拔 / 朝向 Aspect / 水体 / 海风','soil','葡萄园的具体条件'],['土壤 / 排水 / 保水 / 养分 / 黄化 / 腐殖质 / 围墙 / 博斯腾湖 / 风土 / 贵腐','soil','匹配当地需求与课堂视频'],['红葡萄 / 白葡萄 / Merlot / Syrah / Vidal / Gingin / 品种名单','propagation','品种原文、杂交例子与特征对照'],['纬度 / 反射 / 滴灌 / 漫灌 / 火灾 / 烟熏','needs','补全阳光、水分和灾害'],['温度 / 16.5 / 季风 / 新疆 / 山东','climate','气候数字与课堂比较']];
searchTerms.push(['Session 2 / 葡萄园管理 / 整枝 / 密度 / Training / Cordon / Head','s2:training','第二课 · 空间、骨架与高度'],['修剪 / Spur / Cane / Guyot / 冬剪 / 夏剪 / 芽','s2:pruning','第二课 · 木龄和两种冬剪'],['VSP / 冠层 / 搭架 / 叶幕 / Trellising','s2:canopy','第二课 · 光照、通风与成本'],['产量 / 质量 / 平衡 / 摘青 / Green harvesting','s2:balance','第二课 · 资源与负载'],['有机 / 生物动力 / 可持续 / 线虫 / 卷叶 / 皮尔斯 / 病虫害','s2:health','第二课 · 风险与栽培方式'],['采收 / 贵腐 / Hunter Valley / 人工 / 机械 / TBA / Botrytis','s2:harvest','第二课 · 采收决策']);
function search(){const q=$('#search-input').value.trim().toLowerCase();const r=searchTerms.filter(t=>t.join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=r.length?r.map(([t,id,d])=>`<a class="search-result" href="${id.startsWith('s2:')?'#session2/'+id.slice(3):'#lesson/'+id}">${t}<small>${d} ↗</small></a>`).join(''):'<p class="search-empty">已收录课程中未找到这个词。可以试试「砧木」「气候」或「土壤」。</p>';$('#search-results').querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>$('#search-dialog').close()))}
$('#search-open').addEventListener('click',()=>{$('#search-dialog').showModal();search();$('#search-input').focus()});$('#search-input').addEventListener('input',search);$('#sources-open').addEventListener('click',()=>$('#sources-dialog').showModal());$('#coverage-link')?.addEventListener('click',()=>$('#sources-dialog').close());$('#session2-coverage-link')?.addEventListener('click',()=>$('#sources-dialog').close());document.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search-open').click()}});window.addEventListener('hashchange',render);render();

document.addEventListener('click',e=>{const a=e.target.closest?.('[data-book-jump]');if(a){e.preventDefault();document.getElementById(a.dataset.bookJump)?.scrollIntoView({behavior:'smooth',block:'start'});}});
